t.script:
odoo.define('mail.discuss_public_channel_template', function() {
    return {
        data: ,
    };
});
window.pccCourierCall = ;
window.pccEndCourierCall = async function () {
    const config = window.pccCourierCall;
    if (!config || window.pccCourierCallIsEnding) return;
    window.pccCourierCallIsEnding = true;
    try {
        const response = await fetch(config.endUrl, {
            method: 'POST',
            credentials: 'same-origin',
            headers: { 'X-Requested-With': 'XMLHttpRequest' },
        });
        if (!response.ok) throw new Error('Call could not be ended');
        const separator = config.exitUrl.includes('?') ? '&' : '?';
        window.location.assign(config.exitUrl + separator + 'call_ended=1');
    } catch (error) {
        window.pccCourierCallIsEnding = false;
        throw error;
    }
};
document.addEventListener('DOMContentLoaded', function () {
    document.body.classList.add('pcc-call-page');
    if (window.matchMedia('(hover: none) and (pointer: coarse)').matches) {
        document.body.classList.add('pcc-touch-device');
    }
    const closeButton = document.getElementById('pcc_close_call');
    closeButton.addEventListener('click', async function () {
        closeButton.disabled = true;
        try {
            await window.pccEndCourierCall();
        } catch (_error) {
            closeButton.disabled = false;
            closeButton.title = 'Görüşme kapatılamadı. Tekrar deneyin.';
        }
    });
});
(function () {
    const config = window.pccCourierCall;
    const separator = config.exitUrl.includes('?') ? '&' : '?';
    const exitUrl = config.exitUrl + separator + 'call_ended=1';
    const timer = window.setInterval(async function () {
        try {
            const response = await fetch(config.statusUrl, {
                credentials: 'same-origin',
                cache: 'no-store',
            });
            if (!response.ok) return;
            const status = await response.json();
            if (!status.open) {
                window.clearInterval(timer);
                window.location.replace(exitUrl);
            }
        } catch (_error) {
            // A transient network error must not interrupt an active call.
        }
    }, 2000);
})();
